// Host unit test for psp_savedata_crypto (sceChnnlsv savedata crypto).
// Build/run: runtime/tests/run_savedata_crypto.sh   (g++ only)
//
// Test vectors:
//  * AES: FIPS-197 C.1 and NIST SP 800-38A F.2.1 (public).
//  * PPSSPP cross-checks: "REF_*" vectors were generated by compiling
//    PPSSPP's own Core/HLE/sceChnnlsv.cpp + ext/libkirk (master, Oct 2026)
//    and driving it the way SavedataParam::DecryptData/BuildHash do; and our
//    encrypt_file() output (fixed IV) was fed back through PPSSPP's decrypt
//    path, which accepted it with an identical MAC. They are NOT real
//    PPSSPP-written save files -- they cover the algorithm, not file framing
//    beyond [16-byte IV header][ciphertext].
#include "../src/hle/psp_savedata_crypto.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <random>
#include <string>
#include <vector>

using namespace psp_sdcrypto;
using Bytes = std::vector<uint8_t>;

static int g_fail = 0;
#define CHECK(c) do { if (!(c)) { ++g_fail; printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } } while (0)

static Bytes unhex(const char* s) {
    Bytes v;
    for (; s[0] && s[1]; s += 2) { unsigned x; sscanf(s, "%2x", &x); v.push_back(uint8_t(x)); }
    return v;
}
static void fixed_rand(uint8_t* o, size_t n) { for (size_t i = 0; i < n; i++) o[i] = uint8_t(0x30 + i * 5); }

static void test_aes() {
    Bytes key = unhex("000102030405060708090a0b0c0d0e0f"), pt = unhex("00112233445566778899aabbccddeeff"), ct(16), back(16);
    aes128_encrypt_block(key.data(), pt.data(), ct.data());
    CHECK(ct == unhex("69c4e0d86a7b0430d8cdb78070b4c55a"));
    aes128_decrypt_block(key.data(), ct.data(), back.data());
    CHECK(back == pt);

    // SP 800-38A F.2.1 CBC-AES128 with its IV, built from the block primitive.
    Bytes k2 = unhex("2b7e151628aed2a6abf7158809cf4f3c");
    Bytes iv = unhex("000102030405060708090a0b0c0d0e0f");
    Bytes p1 = unhex("6bc1bee22e409f96e93d7e117393172a"), p2 = unhex("ae2d8a571e03ac9c9eb76fac45af8e51");
    Bytes x(16), c1(16), c2(16);
    for (int i = 0; i < 16; i++) x[i] = p1[i] ^ iv[i];
    aes128_encrypt_block(k2.data(), x.data(), c1.data());
    CHECK(c1 == unhex("7649abac8119b246cee98e9b12e9197d"));
    for (int i = 0; i < 16; i++) x[i] = p2[i] ^ c1[i];
    aes128_encrypt_block(k2.data(), x.data(), c2.data());
    CHECK(c2 == unhex("5086cb9b507219ee95db113a917678b2"));

    // Zero-IV CBC over 2 blocks (expected value computed with an independent AES library).
    Bytes pt2 = unhex("6bc1bee22e409f96e93d7e117393172aae2d8a571e03ac9c9eb76fac45af8e51"), out(32);
    aes128_cbc_encrypt(k2.data(), pt2.data(), out.data(), 32);
    CHECK(out == unhex("3ad77bb40d7a3660a89ecaf32466ef97b148c17f309ee692287ae57cf12add49"));
    Bytes dec(32);
    aes128_cbc_decrypt(k2.data(), out.data(), dec.data(), 32);
    CHECK(dec == pt2);
    // in-place with a 20-byte shift (exactly how KIRK CMD7 is invoked on the header buffer)
    Bytes buf(20 + 32, 0xEE);
    memcpy(buf.data() + 20, out.data(), 32);
    aes128_cbc_decrypt(k2.data(), buf.data() + 20, buf.data(), 32);
    CHECK(Bytes(buf.begin(), buf.begin() + 32) == pt2);
}

static const char* KEYHEX = "a0a7aeb5bcc3cad1d8dfe6edf4fb0209";   // key[i] = 0xA0 + 7*i

struct DecVec { int mode; const char* file; const char* plain; const char* mac; };
